public float[] normalizeSumToOne(final float[] a1) {
    float sum = sumArray(a1);
    float[] a2 = new float[a1.length];
    for (int i = 0; i  a2.length; i++) {
        a2[i] = a1[i] / sum;
    }
    return (a2);
}

