public static int[] StringToIntArray(String s) {
    String[] unit = s.split(MDRConstant.seperator);
    int[] value = new int[unit.length];
    for (int i = 0; i  unit.length; i++) {
        value[i] = Integer.parseInt(unit[i]);
    }
    return value;
}

