private int[] convert2int(Vector source) {
    int[] int_matrix = new int[source.size()];
    for (int i = 0; i  int_matrix.length; i++) {
        int_matrix[i] = (int) ((Integer) source.get(i)).intValue();
    }
    return int_matrix;
}
